  });

  const toggle = (id: string) =>
    setOpenGroups((prev) => ({ ...prev, [id]: !prev[id] }));

  const renderItem = (item: NavItem, nested: boolean) => {
    const current = isCurrent(item, pathname);
    const button = (
      <ListItemButton
        component={NextLink}
        href={item.href}
        selected={current}
        aria-current={current ? "page" : undefined}
        onClick={onNavigate}
        sx={{
          minHeight: 44,
          borderRadius: 1,
          mx: 1,
          px: collapsed ? 0 : 2,
          pl: !collapsed && nested ? 4 : undefined,
          justifyContent: collapsed ? "center" : "flex-start",
        }}
      >
        <ListItemIcon
          sx={{
            minWidth: 0,
            mr: collapsed ? 0 : 2,
            justifyContent: "center",
            color: current ? "primary.main" : "inherit",
          }}
        >
          {itemIcons[item.icon]}
        </ListItemIcon>
        {!collapsed && (
          <ListItemText
            primary={item.label}
            slotProps={{
              primary: {
                variant: "body2",
                sx: { fontWeight: current ? 600 : 400 },
              },
            }}
          />
        )}
      </ListItemButton>
    );

    return (
      <li key={item.href}>
        {collapsed ? (
          <Tooltip title={item.label} placement="right">
            {button}
          </Tooltip>
        ) : (
          button
        )}
      </li>
    );
  };

  const renderGroup = (group: NavGroup) => {
    const open = openGroups[group.id];
    const listId = `nav-group-${group.id}`;

    if (collapsed) {
      // Icon rail: a divider and the group's items, no headings.
      return (
        <li key={group.id}>
          <Divider sx={{ my: 1, mx: 2 }} />
          <List component="ul" disablePadding aria-label={group.label}>
            {group.items.map((item) => renderItem(item, false))}
          </List>
        </li>
      );
    }

    return (
      <li key={group.id}>
        <ListItemButton
          onClick={() => toggle(group.id)}
          aria-expanded={open}
          aria-controls={listId}
          sx={{ mx: 1, borderRadius: 1, minHeight: 40 }}
        >
          <ListItemIcon sx={{ minWidth: 0, mr: 2 }}>
            {groupIcons[group.id]}
          </ListItemIcon>
          <ListItemText
            primary={group.label}
            slotProps={{
              primary: {
                variant: "overline",
                sx: { lineHeight: 1.6, color: "text.secondary" },
              },
            }}
          />
          {open ? <ExpandLessIcon /> : <ExpandMoreIcon />}
        </ListItemButton>
        <Collapse in={open} timeout="auto" unmountOnExit>
          <List
            id={listId}
            component="ul"
            disablePadding
            aria-label={group.label}
          >
            {group.items.map((item) => renderItem(item, true))}
          </List>
        </Collapse>
      </li>
    );
  };

  return (
    <List component="ul" sx={{ py: 1 }}>
      {navGroups.map(renderGroup)}
    </List>
  );
}

interface SidebarContentProps extends NavListProps {
  showBrand?: boolean;
}

function Brand({ collapsed }: { collapsed: boolean }) {
  return (
    <Box
