            </Stack>
          </CardContent>
        </Card>

        <Card
          variant="outlined"
          component="section"
          aria-labelledby="notifications-heading"
        >
          <CardContent>
            <Typography
              variant="h6"
              component="h2"
              id="notifications-heading"
              gutterBottom
            >
              Notifications
            </Typography>
            <FormGroup>
              <FormControlLabel
                control={
                  <Switch
                    checked={weekly}
                    onChange={(e) => {
                      setWeekly(e.target.checked);
                      markDirty();
                    }}
                  />
                }
                label="Weekly summary email"
              />
              <FormControlLabel
                control={
                  <Switch
                    checked={mentions}
                    onChange={(e) => {
                      setMentions(e.target.checked);
                      markDirty();
                    }}
                  />
                }
                label="Notify me when I am mentioned on an issue"
              />
              <FormControlLabel
                control={
                  <Switch
                    checked={releases}
                    onChange={(e) => {
                      setReleases(e.target.checked);
                      markDirty();
                    }}
                  />
                }
                label="Release announcements"
