          height={HEIGHT}
          skipAnimation
          xAxis={[{ scaleType: "band", data: weeklyActivity.days }]}
          series={[
            { data: weeklyActivity.opened, label: "Opened" },
            { data: weeklyActivity.closed, label: "Closed" },
          ]}
        />
      ) : (
        <Skeleton variant="rounded" width="100%" height={HEIGHT} />
      )}
    </Box>
  );
}
