                Issues this week
              </Typography>
              <Typography variant="body2" color="text.secondary" gutterBottom>
                Opened and closed per day, all active projects
              </Typography>
              <ActivityChart />
            </CardContent>
          </Card>
        </Grid>

        <Grid size={{ xs: 12, lg: 5 }}>
          <Card
            variant="outlined"
            id="reports"
            component="section"
            aria-labelledby="reports-heading"
            sx={{ height: "100%", scrollMarginTop: 80 }}
          >
            <CardContent>
              <Typography
                variant="h6"
                component="h2"
                id="reports-heading"
                gutterBottom
              >
                Reports
              </Typography>
              <List disablePadding>
                {reports.map((report) => (
                  <ListItem key={report.title} disableGutters divider>
                    <ListItemText
                      primary={report.title}
                      secondary={`${report.detail}. Updated ${formatDate(report.updated)}`}
                    />
                  </ListItem>
                ))}
              </List>
              <Button
                component={NextLink}
                href="/projects"
                size="small"
                sx={{ mt: 1 }}
              >
                View all projects
              </Button>
            </CardContent>
          </Card>
        </Grid>
      </Grid>
    </Box>
  );
}
